    const account = decodeURIComponent(req.url.split('/').at(-2));
    res.end(state.raw ?? JSON.stringify(state.reply ?? { destination, account, units: state.units, unit: 'credits', extra: true }));
  });
  server.listen(0, '127.0.0.1');
  await once(server, 'listening');
  state.origin = "'`http://127.0.0.1:${server.address().port}`;
  servers.push(server);
